// AUDIT-6 Stage B: quick lessons for the new beginnings — the bass first steps, TAB, riffs, the black keys and the five-
// finger positions, the two clefs, chord symbols, sight-reading at the piano, the paradiddle, snare reading in 2/4, 3/4
// and 6/8, the buzz roll; and the Ear course's new topics (rhythm echo, intervals going down, root / 3rd / 5th, which
// note changed). Each opens the first level or topic it prepares (units "tech:<level id>" / "topic:<id>").
import type { NoteEvent, Stimulus } from '../../engine/lesson';
import type { MiniLesson } from '../miniTypes';

const notes = (midis: number[], each = 0.5): Stimulus => ({ kind: 'notes', midis, each });
const chord = (midis: number[], duration = 1.6): Stimulus => ({ kind: 'chord', midis, duration });
const rest = (d: number): Stimulus => ({ kind: 'rest', duration: d });
const ev = (events: NoteEvent[], length: number): Stimulus => ({ kind: 'events', events, length });
type Drum = 'kick' | 'snare' | 'hat';
const KIT: Record<Drum, number> = { kick: 36, snare: 38, hat: 42 };
/** Kit hits [beat, drum, velocity] at `bpm`. */
function kit(bpm: number, beats: number, hits: [number, Drum, number?][]): Stimulus {
  const b = 60 / bpm;
  return ev(hits.map(([t, d, v]) => ({ midi: KIT[d], start: t * b, duration: 0.08, velocity: v ?? (d === 'hat' ? 0.45 : 0.8), perc: d })), beats * b + 0.4);
}
/** A buzz: one stroke and its fading bounces (32nds) on the snare. */
const buzzAt = (t: number): [number, Drum, number?][] => Array.from({ length: 5 }, (_, i) => [t + i / 8, 'snare', 0.75 - i * 0.12]);
const snares = (beats: number[], accentEvery = 0): [number, Drum, number?][] => beats.map((t, i) => [t, 'snare', accentEvery && i % accentEvery === 0 ? 0.95 : 0.55]);

